<?php $auth=app(\App\Services\AuthService::class); $id=(int)$grant['id']; ?>
<div class="dash-head"><div><h1><?= e($grant['title']) ?></h1><p class="sub">Reference <?= e($grant['reference']) ?> · <?= e($grant['status']) ?></p></div><div><a class="btn btn-light" href="<?= e(base_url('admin/grants')) ?>">All grants</a> <?php if ($auth->canAny(['grants.edit','grants.manage'])): ?><a class="btn btn-brand" href="<?= e(base_url('admin/grants/'.$id.'/edit')) ?>">Edit grant</a><?php endif; ?></div></div>
<section class="panel"><h2>Grant details</h2><p><?= nl2br(e((string)($grant['description'] ?: 'No description entered.'))) ?></p><p class="text-muted">Created <?= e((string)$grant['created_at']) ?> UTC</p></section>
<?php if ($assignments!==null): ?><section class="panel"><h2>Assigned users</h2><p class="panel-sub">Removed assignments remain visible as history. An existing user–grant pair cannot be duplicated.</p>
<?php if ($assignments===[]): ?><p>No users assigned.</p><?php endif; ?>
<?php foreach ($assignments as $a): $uid=(int)$a['user_id']; ?><div class="panel" style="margin:14px 0"><strong><?= e(trim($a['first_name'].' '.$a['last_name'])) ?></strong> <span class="text-muted"><?= e($a['email']) ?></span> · <?= e($a['status']) ?><br><small>Assigned <?= e((string)$a['assigned_at']) ?> UTC · by user #<?= (int)$a['assigned_by'] ?></small>
<?php if ($auth->canAny(['users.view','users.manage'])): ?><a href="<?= e(base_url('admin/users/'.$uid)) ?>">View user</a><?php endif; ?>
<?php if ($a['status']!=='removed' && $auth->canAny(['grant_assignments.edit','grant_assignments.manage'])): ?><form method="post" action="<?= e(base_url('admin/grants/'.$id.'/users/'.$uid)) ?>"><?= csrf_field() ?><div class="field"><label>Status</label><select class="input" name="status"><?php foreach (['active','on_hold','completed'] as $state): ?><option value="<?= e($state) ?>" <?= $a['status']===$state ? 'selected' : '' ?>><?= e(str_replace('_',' ',ucfirst($state))) ?></option><?php endforeach; ?></select></div><div class="field"><label>Responsibilities</label><textarea class="input" name="responsibilities" maxlength="1000" rows="2"><?= e((string)$a['responsibilities']) ?></textarea></div><div class="field"><label>Notes</label><textarea class="input" name="notes" maxlength="10000" rows="2"><?= e((string)$a['notes']) ?></textarea></div><button class="btn btn-light" type="submit">Update assignment</button></form><?php else: ?><p>Responsibilities: <?= e((string)($a['responsibilities'] ?: '—')) ?><br>Notes: <?= e((string)($a['notes'] ?: '—')) ?></p><?php endif; ?>
<?php if ($a['status']!=='removed' && $grant['status']!=='closed' && $auth->can('grant_assignments.manage')): ?><form method="post" action="<?= e(base_url('admin/grants/'.$id.'/users/'.$uid.'/change')) ?>" data-confirm="Transfer this assignment? The previous user's assignment will be retained as removed history."><?= csrf_field() ?><div class="field"><label>Change assignee to</label><select class="input" name="new_user_id" required><option value="">Select a different active user</option><?php foreach ($activeUsers as $candidate): if ((int)$candidate['id']===$uid) continue; ?><option value="<?= (int)$candidate['id'] ?>"><?= e(trim($candidate['first_name'].' '.$candidate['last_name']).' · '.$candidate['email']) ?></option><?php endforeach; ?></select></div><input type="hidden" name="responsibilities" value="<?= e((string)$a['responsibilities']) ?>"><input type="hidden" name="notes" value="<?= e((string)$a['notes']) ?>"><button class="btn btn-light" type="submit">Change assignee</button></form><?php endif; ?>
<?php if ($a['status']!=='removed' && $auth->canAny(['grant_assignments.delete','grant_assignments.manage'])): ?><form method="post" action="<?= e(base_url('admin/grants/'.$id.'/users/'.$uid.'/remove')) ?>" data-confirm="Remove this user from this grant? The assignment history will be kept."><?= csrf_field() ?><button class="btn btn-outline-brand" type="submit">Remove assignment</button></form><?php endif; ?></div><?php endforeach; ?></section><?php endif; ?>
<?php if ($assignments!==null && $assignmentEvents!==[]): ?><section class="panel"><h2>Assignment history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>When</th><th>User ID</th><th>Action</th><th>By</th><th>Before → after</th></tr></thead><tbody><?php foreach ($assignmentEvents as $event): ?><tr><td><?= e((string)$event['created_at']) ?> UTC</td><td>#<?= (int)$event['user_id'] ?></td><td><?= e($event['action']) ?></td><td>#<?= (int)$event['actor_user_id'] ?></td><td><?= e((string)($event['from_status'] ?: '—').' → '.($event['to_status'] ?: '—')) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if ($grant['status']!=='closed' && $auth->canAny(['grant_assignments.create','grant_assignments.manage'])): ?><section class="panel"><h2>Assign users</h2><p class="panel-sub">Select one or several active users (Ctrl/Cmd-click for multiple). A batch is all-or-nothing.</p><form method="post" action="<?= e(base_url('admin/grants/'.$id.'/users')) ?>"><?= csrf_field() ?><div class="field"><label for="user_ids">Active users</label><select class="input" id="user_ids" name="user_ids[]" multiple size="8" required><?php foreach ($activeUsers as $user): ?><option value="<?= (int)$user['id'] ?>"><?= e(trim($user['first_name'].' '.$user['last_name']).' · '.$user['email'].' (#'.$user['id'].')') ?></option><?php endforeach; ?></select></div><div class="field"><label for="responsibilities">Responsibilities (optional)</label><textarea class="input" id="responsibilities" name="responsibilities" maxlength="1000" rows="2"></textarea></div><div class="field"><label for="notes">Notes (optional)</label><textarea class="input" id="notes" name="notes" maxlength="10000" rows="2"></textarea></div><button class="btn btn-brand" type="submit">Assign selected users</button></form></section><?php endif; ?>
